package io.aetheris.orchestrator.api;import io.aetheris.orchestrator.evaluation.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/orchestrator/stage8/evaluations") public class EvaluationController {private final EvaluationService service;public EvaluationController(EvaluationService service){this.service=service;}@PostMapping public EvaluationRunEntity record(@RequestBody EvaluationRequest r){return service.record(r);}@GetMapping public List<EvaluationRunEntity> recent(){return service.recent();}@GetMapping("/average") public Map<String,Object> average(@RequestParam String subjectType,@RequestParam String subjectId){return Map.of("subjectType",subjectType,"subjectId",subjectId,"averageScore",service.average(subjectType,subjectId));}}
